@push('scripts')
<script>
document.addEventListener('DOMContentLoaded',()=>{
 const room=document.getElementById('transferRoom'),rent=document.getElementById('transferRent');
 const format=()=>{const raw=rent.value.replaceAll(',','');const valid=/^\d+(?:\.\d{0,2})?$/.test(raw);rent.setCustomValidity(valid?'':'Enter a valid amount with up to two decimals.');if(valid){const [whole,fraction]=raw.split('.');rent.value=whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(fraction===undefined?'':'.'+fraction);}};
 room.addEventListener('change',()=>{const value=room.selectedOptions[0]?.dataset.rate;if(value!==undefined&&value!=='')rent.value=value;format();});rent.addEventListener('input',format);format();
});
</script>
